from lib import *
S = SS('g39')
steps = [
    step("存活堆 50.23 MB(刚做完一次 GC 时 runtime/metrics 读到的 /gc/heap/live:bytes),4 个 goroutine 持续分配垃圾 2 秒,不同 GOGC。运行开始时的堆目标与公式 目标 = 存活堆 × (1 + GOGC/100) 吻合:GOGC=25 时 62.8 MB(预测 62.8)、50 时 75.4(75.3)、100 时 100.7(100.5)、200 时 151.1(150.7)、400 时 251.9(251.1)、800 时 453.6(452.1),误差都不超过 1.5 MB。运行结束时读到的目标更大(GOGC=100 时 142.0 MB),并且与分配速度有关:1、2、4 个分配 goroutine 结束时的目标分别是 118.3、140.3、141.8 MB。", t=tl(S(1)), done=lidx(S(1), 'GOGC= 25', 'GOGC=100:存活堆', 'GOGC=800:存活堆'), mark=lidx(S(1), '结束时的目标', '1 个分配 goroutine', '4 个分配 goroutine'), b=bars([['GOGC=25 开始时目标', 62.8, '62.8'], ['GOGC=100', 100.7, '100.7'], ['GOGC=200', 151.1, '151.1'], ['GOGC=400', 251.9, '251.9'], ['GOGC=800', 453.6, '453.6']], 453.6, done=[0, 1, 2, 3, 4]), kv=KV([['公式', '目标 ≈ 存活堆 × (1 + GOGC/100)'], ['存活堆 50.23 MB, GOGC=100', '开始时目标 100.7 MB(预测 100.5)'], ['结束时的目标', '比开始时大,分配越快越大:118.3 / 140.3 / 141.8 MB']], ['公式'])),
    step("GOGC 的取舍(同样的 2 秒,4 个分配 goroutine):GOGC=25:GC 313 次,assist 3560 ms,峰值堆约 69 MB,吞吐 44.5 M 次分配/秒;50:242 次,assist 2359 ms,89 MB,73.9;100:151 次,assist 755 ms,144 MB,110.0;200:95 次,assist 65 ms,261 MB,140.5;400:59 次,assist 38 ms,481 MB,161.2;800:32 次,assist 26 ms,912 MB,177.7。GOGC 越大 GC 越少、吞吐越高,代价是内存占用。(“GC CPU 合计”包含空闲 P 上的标记 worker 时间,所以会超过 2 秒,没有放进图里。)", t=tl(S(2)), done=lidx(S(2), 'GOGC= 25', 'GOGC= 50', 'GOGC=100'), mark=lidx(S(2), 'GOGC=200', 'GOGC=400', 'GOGC=800'), b=bars([['GOGC=25 吞吐(M/s)', 44.5, '44.5'], ['GOGC=100', 110.0, '110.0'], ['GOGC=400', 161.2, '161.2'], ['GOGC=800', 177.7, '177.7']], 177.7, done=[0, 1], mark=[2, 3]), kv=KV([['GC 次数', 'GOGC=25 → 800:313 → 32'], ['峰值堆', '69 MB → 912 MB'], ['吞吐', '44.5 → 177.7 M 次分配/秒'], ['assist', '3560 ms → 26 ms']], ['吞吐'])),
    step("GOGC=off 运行 1 秒:gctrace 里没有任何一次由分配触发的 GC,cycles=0,HeapSys 涨到 5952 MB;运行中途 debug.SetGCPercent(400) 返回旧值 100,metrics 里的 gogc 从 100 变成 400,堆目标从 100.7 MB 变成 371.9 MB;gctrace 里的 “MB goal” 序列前半是 7 17 32 63 100 119,后半是 370 342 400 361 369 357。", t=tl(S(3)), done=lidx(S(3), 'GOGC=off'), mark=lidx(S(3), 'SetGCPercent(400)', 'MB goal'), kv=KV([['GOGC=off', '1 秒内堆涨到 5952 MB,没有 GC'], ['debug.SetGCPercent(400)', '返回旧值 100,目标从 100.7 MB 变成 371.9 MB'], ['gctrace 的 MB goal', '前半约 100,后半约 360–400']], ['GOGC=off'])),
    step("最小堆目标 4 MB:存活堆只有 1.22 MB 时,堆目标是 4.0 MB,1 秒里完成了 1306 次 GC(gctrace 里 gc 1、2、3 分别在 0.000s、0.001s、0.001s,堆是 1→1→1、3→4→1、3→3→1 MB)。", t=tl(S(4)), done=lidx(S(4), 'gogc=100→100'), mark=lidx(S(4), 'gc 1 @0.000s', 'gc 2 @0.001s'), kv=KV([['存活堆', '1.22 MB'], ['堆目标', '4.0 MB(最小值)'], ['1 秒内 GC', '1306 次']], ['堆目标'])),
    step("分配得快会触发 mark assist(分配的 goroutine 被要求帮忙标记):存活堆 200 MB,把分配 goroutine 从 1 加到 4、8:GC 次数都是 42–44 次,assist 时间 6 ms、338 ms、2218 ms,吞吐 79.8、110.4、114.4 M 次分配/秒。", t=tl(S(5)), done=lidx(S(5), '1 个分配 goroutine'), mark=lidx(S(5), '4 个分配 goroutine', '8 个分配 goroutine'), b=bars([['1 个 goroutine:assist(ms)', 6, '6'], ['4 个', 338, '338'], ['8 个', 2218, '2218']], 2218, done=[0], mark=[1, 2]), kv=KV([['GC 次数', '42 / 43 / 44(几乎不变)'], ['assist', '6 → 338 → 2218 ms'], ['吞吐', '79.8 → 110.4 → 114.4 M 次/秒']], ['assist'])),
]
A = mkartg('g39', 39, 'Go,GC,GOGC,pacer,堆目标,mark assist,真实验证,动画演示',
    '在 Go 1.27.1 里验证 GC 的触发:刚做完一次 GC 时堆目标 = 存活堆 × (1 + GOGC/100)(6 种 GOGC 的预测误差 ≤ 1.5 MB);运行中分配越快目标越大;GOGC 从 25 到 800 时 GC 次数 313 → 32、吞吐 44.5 → 177.7 M 次/秒、峰值堆 69 → 912 MB;GOGC=off 一秒内堆涨到 5952 MB;debug.SetGCPercent 运行时生效;最小堆目标 4 MB 下每秒 1306 次 GC;分配 goroutine 增多时 mark assist 从 6 ms 涨到 2218 ms。',
    '“堆长到多大才触发下一轮 GC”由 GOGC 控制,但真实行为比一个公式复杂:存活堆怎么算、标记期间分配的对象算不算、最小堆多大、分配太快时会发生什么。这篇用 runtime/metrics 与 gctrace 逐项验证,并量出 GOGC 在内存与吞吐之间的取舍。',
    [('≤ 1.5 MB', '刚完成一次 GC 时,堆目标与 存活堆 × (1 + GOGC/100) 的差'), ('313 → 32', 'GOGC 从 25 提高到 800,2 秒内 GC 的次数'), ('2218 ms', '8 个分配 goroutine 在存活堆 200 MB 下花在 mark assist 上的时间')],
    [('目标怎么来的', '<p>用 <code>runtime/metrics</code> 读到 <code>/gc/heap/live:bytes</code>(上一轮标记结束时的存活堆)和 <code>/gc/heap/goal:bytes</code>,两者在 6 种 GOGC 下都符合 <code>goal ≈ live × (1 + GOGC/100)</code>(这个程序里栈与全局变量很小,公式里它们的项可以忽略)。运行中读到的目标会更大,并且和分配速度正相关——源码里说标记阶段新分配的对象直接标成黑色,所以分配得快时这部分“漂浮垃圾”被算进了存活堆。这是我对现象的解释,没有单独隔离验证。</p>'),
     ('GOGC 的取舍', '<p>GOGC 越大,GC 越稀,mutator 被 assist 打扰越少、吞吐越高,但峰值堆越大。这个分配密集的负载里,吞吐从 44.5 涨到 177.7 M 次/秒,峰值堆从 69 涨到 912 MB。没有“最好”的值,取决于你愿意用多少内存换多少吞吐;容器里还要结合内存上限(见下一篇 GOMEMLIMIT)。</p>'),
     ('关掉与运行时调整', '<p><code>GOGC=off</code> 之后分配不再触发 GC,堆线性增长(1 秒涨到近 6 GB,这个实验只能跑 1 秒)。<code>debug.SetGCPercent</code> 可以在运行时改,返回旧值,从下一轮开始生效。</p>'),
     ('最小堆目标', '<p>存活堆很小时,目标不会低于 4 MB,所以一个只有 1 MB 存活数据、高速分配的程序每秒会触发上千次 GC。这是 GC 频率与存活堆大小脱钩的情形,可以用 <code>GOGC</code> 调大或者给一块“压舱石”内存来减少 GC(后面一篇用 GOMEMLIMIT 的做法,本文没有试压舱石)。</p>'),
     ('mark assist', '<p>如果分配速度超过后台标记的速度,分配的 goroutine 会被要求先帮忙标记(assist)再继续分配,表现为 gctrace 里 CPU 时间第一段非零。实验里 GC 次数几乎不变,但 assist 从 6 ms 涨到 2218 ms,说明 assist 才是“分配太快”最直接的信号。</p>')],
    steps,
    [ENV_G + '。存活堆是 N 个 56 字节节点串成的图(runtime.GC() 后 50.23 MB);分配 goroutine 不停地 new 小对象并丢弃;堆目标、存活堆来自 runtime/metrics,GC 次数与 assist 来自 GODEBUG=gctrace=1 的逐行解析(把每行 CPU 时间各列相加,含空闲 P 上的标记 worker,所以合计可以超过墙钟时间);每个设置只跑一次',
     '没有验证:栈与全局变量对目标的贡献(程序里它们很小)、GOMEMLIMIT 与 GOGC 的交互(见下一篇)、漂浮垃圾对目标的影响的隔离实验、多次重复运行的离散度、amd64 上的数字、sync.Pool 与 GC 的关系'],
    'GC 触发与 GOGC')
